export const CALENDAR_EXTS: ReadonlySet<string> = new Set(["ics", "ical", "icalendar"]);
export const MARKDOWN_EXTS: ReadonlySet<string> = new Set(["md", "markdown"]);
/** Delimited text with a better shape available than a wall of commas. */
export const TABLE_EXTS: ReadonlySet<string> = new Set(["csv", "tsv"]);

/** Extensions that render as text. */
export const TEXT_READABLE_EXTS: ReadonlySet<string> = new Set([
    // plain / docs / data
    "txt", "log", "md", "markdown", "rst", "tex", "csv", "tsv", "json", "jsonc",
    "xml", "yaml", "yml", "toml", "ini", "cfg", "conf", "env", "properties",
    "diff", "patch", "sql", "graphql", "proto",
    // subtitles: they ride alongside the videos they belong to
    "srt", "vtt", "ass", "ssa",
    // web
    "html", "htm", "css", "scss", "less", "styl", "svg",
    "js", "mjs", "cjs", "jsx", "ts", "tsx", "vue", "svelte",
    // general programming
    "py", "rb", "php", "go", "rs", "java", "kt", "kts", "scala", "swift", "dart",
    "c", "h", "cpp", "cc", "hpp", "cs", "lua", "pl", "r", "sh", "bash", "zsh",
    "fish", "bat", "ps1", "gradle", "dockerfile", "makefile",
    // dotfiles / config files (".gitignore" has the extension "gitignore")
    "gitignore", "gitattributes", "editorconfig", "npmrc", "dockerignore",
    "prettierrc", "babelrc",
]);

/** Base names (lowercased) that are text even with no extension. */
export const EXTENSIONLESS_TEXT_NAMES: ReadonlySet<string> = new Set([
    "dockerfile", "makefile", "readme", "license", "licence", "changelog",
    "authors", "notice", "copying", ".gitignore", ".gitattributes", ".env",
    ".editorconfig", ".npmrc", ".dockerignore", ".prettierrc", ".babelrc",
]);

const TEXT_APPLICATION_MIMES: ReadonlySet<string> = new Set([
    "application/json", "application/xml", "application/javascript",
    "application/x-yaml", "application/x-sh", "application/toml",
    "application/x-www-form-urlencoded",
]);

function bareMime(mime: string | null | undefined): string {
    return (mime ?? "").split(";")[0].trim().toLowerCase();
}

/** A mime type that says "this is text", whatever the name says. */
export function isTextMime(mime: string | null | undefined): boolean {
    const m = bareMime(mime);
    if (!m) return false;
    return m.startsWith("text/") || TEXT_APPLICATION_MIMES.has(m);
}

/** Whether the text viewer can show this file. */
export function isTextReadable(name: string, mime?: string | null): boolean {
    const ext = extOf(name);
    if (ext && TEXT_READABLE_EXTS.has(ext)) return true;
    if (!ext && EXTENSIONLESS_TEXT_NAMES.has(name.toLowerCase())) return true;
    return isTextMime(mime);
}

export function isOfficeExt(ext: string): boolean {
    return OFFICE_DOCUMENT_EXTS.has(ext) || OFFICE_SPREADSHEET_EXTS.has(ext) || OFFICE_PRESENTATION_EXTS.has(ext);
}

// ── The two questions ──────────────────────────────────────────────────────

/**
 * Which viewer opens a file.
 *
 * The order is the web viewer's dispatch order and it is load-bearing: a
 * .vcf is text but reads better as a contact, an .ics as a calendar; an .svg
 * is text but is drawn; an .fb2 is XML but is a book; a .cbz is a zip but is a comic; a .csv is
 * text and an office format, but a table is the best shape for it.
 */
export type PreviewKind =
    | "contact"
    | "calendar"
    | "image"
    | "video"
    | "audio"
    | "pdf"
    | "ebook"
    | "archive"
    | "markdown"
    | "table"
    | "text"
    | "office"
    /** Decoded in the browser, behind an Open button (CLIENT_DECODE_EXTS). */
    | "decode"
    | "none";

export function previewKindFor(name: string, mime?: string | null): PreviewKind {
    const ext = extOf(name);
    if (CONTACT_EXTS.has(ext)) return "contact";
    if (CALENDAR_EXTS.has(ext)) return "calendar";
    if (IMAGE_PREVIEW_EXTS.has(ext)) return "image";
    if (VIDEO_EXTS.has(ext)) return "video";
    if (AUDIO_EXTS.has(ext)) return "audio";
    if (PDF_EXTS.has(ext)) return "pdf";
    if (BOOK_READABLE_EXTS.has(ext)) return "ebook";
    if (ARCHIVE_BROWSABLE_EXTS.has(ext)) return "archive";
    if (MARKDOWN_EXTS.has(ext)) return "markdown";
    if (TABLE_EXTS.has(ext)) return "table";
    if (isTextReadable(name, mime)) return "text";
    if (isOfficeExt(ext)) return "office";
    if (CLIENT_DECODE_EXTS.has(ext)) return "decode";
    // A name that says nothing (no extension, or one no list knows) can still
    // carry a specific mime. Never let the mime override a known extension: a
    // .dng sniffed as image/x-adobe-dng must not reach the image viewer.
    if (!(ext in FAMILY_BY_EXT)) {
        const m = bareMime(mime);
        if (DRAWABLE_IMAGE_MIMES.has(m)) return "image";
        if (m.startsWith("video/")) return "video";
        if (m.startsWith("audio/")) return "audio";
        if (m === "application/pdf") return "pdf";
    }
    return "none";
}

/** Image mimes a browser draws (or the server thumbnails, for HEIC/HEIF). */
const DRAWABLE_IMAGE_MIMES: ReadonlySet<string> = new Set([
    "image/png", "image/jpeg", "image/gif", "image/webp", "image/avif", "image/bmp",
    "image/svg+xml", "image/x-icon", "image/vnd.microsoft.icon", "image/heic", "image/heif",
]);

/** What a file is, independent of whether anything can show it. */
export type ContentFamily =
    | "image"
    | "video"
    | "audio"
    | "pdf"
    | "document"
    | "spreadsheet"
    | "presentation"
    | "text"
    | "ebook"
    | "archive"
    | "other";

const FAMILY_BY_EXT: Record<string, ContentFamily> = {};
function claim(family: ContentFamily, ...sets: ReadonlySet<string>[]): void {
    for (const set of sets) {
        for (const ext of set) if (!(ext in FAMILY_BY_EXT)) FAMILY_BY_EXT[ext] = family;
    }
}
// Earlier claims win, so the order settles the overlaps: a .csv is a
// spreadsheet (not text), an .svg an image, a .vcf and an .ics text.
claim("image", IMAGE_PREVIEW_EXTS, IMAGE_FAMILY_ONLY_EXTS);
claim("video", VIDEO_EXTS);
claim("audio", AUDIO_EXTS);
claim("pdf", PDF_EXTS);
claim("document", OFFICE_DOCUMENT_EXTS, DOCUMENT_FAMILY_ONLY_EXTS);
claim("spreadsheet", OFFICE_SPREADSHEET_EXTS, SPREADSHEET_FAMILY_ONLY_EXTS);
claim("presentation", OFFICE_PRESENTATION_EXTS, PRESENTATION_FAMILY_ONLY_EXTS);
claim("ebook", BOOK_READABLE_EXTS, BOOK_FAMILY_ONLY_EXTS);
claim("archive", ARCHIVE_BROWSABLE_EXTS, ARCHIVE_FAMILY_ONLY_EXTS);
claim("text", CONTACT_EXTS, CALENDAR_EXTS, TEXT_READABLE_EXTS);

/**
 * Classify a file by name, falling back to its mime type when the name says
 * nothing. Rows written before mime sniffing store application/octet-stream
 * for everything, which tells us nothing, so that mime is ignored.
 */
export function contentFamilyFor(name: string, mime?: string | null): ContentFamily {
    const ext = extOf(name);
    const byExt = FAMILY_BY_EXT[ext];
    if (byExt) return byExt;
    if (!ext && EXTENSIONLESS_TEXT_NAMES.has(name.toLowerCase())) return "text";

    const m = bareMime(mime);
    if (m && m !== "application/octet-stream") {
        if (m === "application/pdf") return "pdf";
        if (m.startsWith("image/")) return "image";
        if (m.startsWith("video/")) return "video";
        if (m.startsWith("audio/")) return "audio";
        if (isTextMime(m)) return "text";
    }
    return "other";
}
